from itertools import combinations

def count_connected(n):
    """Number of connected topologies on range(n)."""
    X = frozenset(range(n))
    subs = [frozenset(c) for r in range(n + 1) for c in combinations(range(n), r)]
    count = 0
    for mask in range(2 ** len(subs)):
        tau = {s for k, s in enumerate(subs) if mask >> k & 1}
        if frozenset() not in tau or X not in tau:
            continue
        if any(U | V not in tau or U & V not in tau for U in tau for V in tau):
            continue
        if not any(U and U != X and (X - U) in tau for U in tau):
            count += 1
    return count
